// Map Podchaser GraphQL response to ListenNotes-compatible shape
const items = $input.all();
const out = [];
for (const item of items) {
  const resp = item.json || {};
  // Handle GraphQL errors cleanly
  if (resp.errors && resp.errors.length > 0) {
    throw new Error('Podchaser GraphQL error: ' + JSON.stringify(resp.errors).slice(0, 300));
  }
  const podcasts = ((resp.data || {}).podcasts || {}).data || [];
  for (const p of podcasts) {
    out.push({ json: {
      id: String(p.id),
      title: p.title || '',
      title_original: p.title || '',
      publisher: (p.author && p.author.name) || '',
