      rating: p.ratingAverage || null,
      total_episodes: p.numberOfEpisodes || 0,
      latest_pub_date_ms: p.latestEpisodeDate ? new Date(p.latestEpisodeDate).getTime() : null
    }});
  }
}
return out;

