// Haiku runs once per conference; flatten nested speaker arrays into one item per speaker
const items = $input.all();
const confs = $('P2: Apify Fetch Crawl Items').all();
const out = [];
for (let i = 0; i < items.length; i++) {
  let speakers = [];
  try {
    const text = items[i].json?.content?.[0]?.text || '';
    const cleaned = text.replace(/^```json\s*|\s*```$/g, '').trim();
    speakers = JSON.parse(cleaned);
    if (!Array.isArray(speakers)) speakers = [];
  } catch (e) {
    console.log('haiku parse err:', e.message);
    speakers = [];
  }
  const conf = confs[i]?.json?.userData || {};
  for (const s of speakers) {
    if (!s.name) continue;
    out.push({ json: {
      name: s.name,
      title: s.title || null,
      company: s.company || null,
      session_title: s.session_title || null,
      bio_snippet: s.bio_snippet || null,
      conference_name: conf.name || null,
      conference_category: conf.category || null
    } });
  }
}
return out.length > 0 ? out : [{ json: { skipped: true, reason: 'no speakers extracted' } }];

