const item = $input.first().json;
let text = item.content?.[0]?.text || item.text || '';
let trimmed = (text || '').trim();
let fenced = trimmed;
if (fenced.startsWith('```')) {
  fenced = fenced.replace(/^```(?:json)?\n?/, '').replace(/\n?```$/, '');
}
let parsed = null;
try {
  const maybe = JSON.parse(fenced);
  if (maybe && typeof maybe === 'object' && maybe.skip === true) {
    parsed = maybe;
  }
} catch (e) {
  parsed = null;
}
if (parsed) {
  return [{ json: { skip: true, reason: parsed.reason || 'no verifiable stat', raw_text: text.slice(0, 1000) } }];
}
return [{ json: { skip: false, content: [{ text }] } }];
